/* ── lc.js (ported from truck-dashboard/src/lib/lc.js) ─────────────────────────── */
// LC (letter of credit) date and HTC helpers shared by the planner views.
const LC_SOON_DAYS = 15;
const AGEING_HIGH_DAYS = 15;
const isAgeingHigh = (d) => d != null && d > AGEING_HIGH_DAYS;
const HTC_CATEGORIES = ['FN', 'Q', 'Q & T'];

const DAY = 86400000;
const startOfToday = () => { const d = new Date(); d.setHours(0, 0, 0, 0); return d.getTime(); };

// "31-10-2026 00:00", "31/10/2026" or an Excel serial number -> local midnight timestamp, or null.
function parseLcDate(value) {
  if (value === '' || value === null || value === undefined) return null;
  let d = null;
  if (typeof value === 'number' && value > 20000 && value < 80000) {
    const u = new Date(Math.round((value - 25569) * DAY)); // Excel serial -> UTC date
    d = new Date(u.getUTCFullYear(), u.getUTCMonth(), u.getUTCDate());
  } else if (value instanceof Date && !isNaN(value)) {
    d = new Date(value.getFullYear(), value.getMonth(), value.getDate());
  } else {
    const m = String(value).trim().match(/^(\d{1,2})[-/.](\d{1,2})[-/.](\d{2,4})/);
    if (m) d = new Date(Number(m[3].length === 2 ? '20' + m[3] : m[3]), Number(m[2]) - 1, Number(m[1]));
  }
  return d && !isNaN(d) ? d.getTime() : null;
}
function formatLc(ts) {
  if (ts == null) return '';
  const d = new Date(ts);
  return String(d.getDate()).padStart(2, '0') + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + d.getFullYear();
}
const lcDaysLeft = (ts) => (ts == null ? null : Math.round((ts - startOfToday()) / DAY));
const isLcSoon = (ts) => ts != null && lcDaysLeft(ts) < LC_SOON_DAYS; // includes dates already passed
const htcGroup = (htc) => (String(htc || '').trim() ? 'HTC' : 'Non-HTC');

// 'SO/item' -> HTC and LC details of that plan line (trucks and LTL items only carry the SO/item key).
function buildSoMeta(rows) {
  const map = new Map();
  for (const r of rows) {
    map.set(r.so + '/' + r.soItm, { htc: r.htc || '', group: htcGroup(r.htc), lcTs: r.lcTs ?? null, lcSoon: isLcSoon(r.lcTs ?? null), ageing: r.ageing ?? null });
  }
  return map;
}

// Plan-wide filter chosen with the pills under the KPI tiles.
function matchesPlanFilter(filter, meta) {
  if (!filter || filter === 'all') return true;
  if (!meta) return false;
  if (filter === 'htc') return meta.group === 'HTC';
  if (filter === 'nonhtc') return meta.group === 'Non-HTC';
  if (filter === 'lc') return meta.lcSoon;
  if (filter === 'ageing') return isAgeingHigh(meta.ageing);
  return true;
}

/* ── engine.js (ported from truck-dashboard/src/lib/engine.js) ─────────────────────────── */
// Truck load optimization engine — pure functions, no DOM access.
// Rules implemented (per dispatch-plan business logic):
//  1. Truck sizes: 40, 32, 28/26 MT.
//  2. ODC mix: a load is pure ODC, pure NON-ODC, or mixed with ODC >= 60% of load weight.
//  3. FTL (40 MT) preferred; LTL clubs at most 2 distinct customers.
//  4. Priority: 40 MT (single, then clubbed) -> 32 MT (single, then clubbed) -> 28/26 MT (suggestion only) -> LTL.
//  5. Clubbed parties must have destinations <= 100 km apart (haversine).
//
// Converted to an ES module for the React/Vite migration (see HANDOFF_CONTEXT.md).
// IMPORTANT: no algorithm/logic changes were made in this conversion — only the
// exposure mechanism (window.TruckEngine global -> ES `export`) changed. The
// window.TruckEngine attachment is kept at the bottom for anything that still expects it.



const DENSITY_T_PER_M3 = 7.85;
const ODC_MIN_SHARE = 0.60;
const CLUB_RADIUS_KM = 100;
const EARTH_RADIUS_KM = 6371;
// Standard trailer envelope — a plate exceeding either dimension is what makes the load ODC.
const ODC_WIDTH_LIMIT_M = 2.5;
const ODC_LENGTH_LIMIT_M = 12.5;

// Export notions are routed to their shipping ports, regardless of the destination
// text supplied in the dispatch plan.
const EXPORT_DESTINATIONS = {
  'CT PICP SEPT': { label: 'PARADEEP PORT', coords: [20.2667, 86.7042] },
  'CT VIZAG SEPT': { label: 'VIZAG PORT', coords: [17.6868, 83.2185] },
};

const TRUCK_TIERS = [
  // Bands widened (lower bound pulled down) so more real-world loads qualify at each
  // tier before falling through to the one below. Clubbing is single-dock or a
  // 2-dock club only — never more than 2 distinct customers per truck (rule 3).
  { id: '40MT', label: '40 MT FTL', target: 40, band: [36, 40], suggestion: false },
  { id: '32MT', label: '32 MT', target: 32, band: [26, 32], suggestion: false },
  { id: '28_26MT', label: '28/26 MT (last resort)', target: 27, band: [20, 28], suggestion: true },
];

function normalizeCityKey(raw) {
  if (!raw) return '';
  let s = String(raw).toUpperCase();
  s = s.replace(/[^A-Z ]/g, ' ').replace(/\s+/g, ' ').trim();
  return s;
}

const CITY_SUFFIXES = [' DISTRICT', ' RURAL', ' URBAN', ' CANTONMENT', ' CITY'];

function tryLastToken(key, table) {
  const tokens = key.split(' ').filter(Boolean);
  if (tokens.length > 1) {
    const last = tokens[tokens.length - 1];
    if (last.length > 3 && table[last]) return { coords: table[last], matchedAs: last };
  }
  return null;
}

function levenshtein(a, b) {
  if (a === b) return 0;
  const al = a.length, bl = b.length;
  if (al === 0) return bl;
  if (bl === 0) return al;
  let prev = new Array(bl + 1);
  let curr = new Array(bl + 1);
  for (let j = 0; j <= bl; j++) prev[j] = j;
  for (let i = 1; i <= al; i++) {
    curr[0] = i;
    for (let j = 1; j <= bl; j++) {
      const cost = a[i - 1] === b[j - 1] ? 0 : 1;
      curr[j] = Math.min(prev[j] + 1, curr[j - 1] + 1, prev[j - 1] + cost);
    }
    [prev, curr] = [curr, prev];
  }
  return prev[bl];
}

// Last-resort fuzzy match against the city table: only used after exact/suffix/last-token
// matching has failed. Threshold scales with name length but stays tight (max 2) so we
// don't conflate genuinely different cities.
function fuzzyMatchCity(key, table) {
  if (!key || key.length < 4) return null;
  const maxDist = key.length <= 5 ? 1 : 2;
  let best = null, bestDist = Infinity;
  for (const candidate in table) {
    if (Math.abs(candidate.length - key.length) > maxDist) continue;
    const d = levenshtein(key, candidate);
    if (d < bestDist) { bestDist = d; best = candidate; }
  }
  if (best && bestDist <= maxDist) return { matchedAs: best, dist: bestDist };
  return null;
}

function resolveCity(raw, table) {
  const key = normalizeCityKey(raw);
  if (!key) return { key, coords: null, matchedAs: null };
  if (table[key]) return { key, coords: table[key], matchedAs: key };

  // Strip known administrative suffixes (DISTRICT, RURAL, ...) and retry both the
  // stripped string and its own last token (e.g. "SPSR NELLORE DISTRICT" -> "SPSR NELLORE" -> "NELLORE").
  for (const suf of CITY_SUFFIXES) {
    if (key.endsWith(suf)) {
      const stripped = key.slice(0, -suf.length).trim();
      if (table[stripped]) return { key, coords: table[stripped], matchedAs: stripped };
      const viaLast = tryLastToken(stripped, table);
      if (viaLast) return { key, coords: viaLast.coords, matchedAs: viaLast.matchedAs };
    }
  }
  const viaLast = tryLastToken(key, table);
  if (viaLast) return { key, coords: viaLast.coords, matchedAs: viaLast.matchedAs };

  // Last resort: fuzzy/typo-tolerant match (e.g. "HARIDAWAR" -> "HARIDWAR").
  const fuzzy = fuzzyMatchCity(key, table);
  if (fuzzy) {
    return { key, coords: table[fuzzy.matchedAs], matchedAs: fuzzy.matchedAs, fuzzy: true, fuzzyDist: fuzzy.dist };
  }
  return { key, coords: null, matchedAs: null };
}

function haversineKm(a, b) {
  const toRad = (d) => (d * Math.PI) / 180;
  const dLat = toRad(b[0] - a[0]);
  const dLon = toRad(b[1] - a[1]);
  const lat1 = toRad(a[0]);
  const lat2 = toRad(b[0]);
  const h = Math.sin(dLat / 2) ** 2 + Math.cos(lat1) * Math.cos(lat2) * Math.sin(dLon / 2) ** 2;
  return 2 * EARTH_RADIUS_KM * Math.asin(Math.sqrt(h));
}

function round2(n) { return Math.round(n * 100) / 100; }

function exportDestinationFor(row) {
  const candidates = [
    row['Ship To Party Name'],
    row['Ship To Party City'],
    row['Sold To Party Name'],
    row['Dch_Desc'],
    row['Pending Dispatch Remarks'],
  ];
  for (const candidate of candidates) {
    const destination = EXPORT_DESTINATIONS[normalizeCityKey(candidate)];
    if (destination) return destination;
  }
  return null;
}

// --- Row preprocessing -----------------------------------------------------

function buildRows(rawRows, cityTable) {
  const foreignSet = new Set((typeof window !== 'undefined' && window.INDIA_CITY_FOREIGN_KEYS) || []);
  return rawRows.map((r, idx) => {
    const thickMm = Number(r['Thick']) || 0;
    const widthMm = Number(r['Width']) || 0;
    const lengthM = Number(r['Length']) || 0;
    const planMT = Number(r['Dispatch Plan']) || 0;
    const underLoadingMT = Number(r['Under Loading']) || 0;
    const totalMT = Math.max(0, planMT - underLoadingMT); // quantity still to dispatch: plan minus what is already being loaded
    const lcTs = parseLcDate(r['LC LS Dt']);
    const plateWeightMT = (thickMm / 1000) * (widthMm / 1000) * lengthM * DENSITY_T_PER_M3;
    const plateCount = plateWeightMT > 0 ? Math.max(1, Math.round(totalMT / plateWeightMT)) : 1;
    const unitWeight = plateCount > 0 ? totalMT / plateCount : totalMT;
    const sourceCityRaw = r['Ship To Party City'] || '';
    const exportDestination = exportDestinationFor(r);
    const cityRaw = exportDestination ? exportDestination.label : sourceCityRaw;
    const resolved = exportDestination
      ? { key: normalizeCityKey(cityRaw), coords: exportDestination.coords, matchedAs: normalizeCityKey(cityRaw) }
      : resolveCity(cityRaw, cityTable);
    const isForeign = resolved.matchedAs ? foreignSet.has(resolved.matchedAs) : false;
    const odcRaw = String(r['ODC Remarks'] || '').toUpperCase().trim();
    const exceedsOdcEnvelope = widthMm / 1000 > ODC_WIDTH_LIMIT_M || lengthM > ODC_LENGTH_LIMIT_M;
    const isODC = odcRaw === 'ODC' || (odcRaw !== 'NON ODC' && odcRaw.includes('ODC')) || exceedsOdcEnvelope;
    return {
      rowIndex: idx,
      so: r['SO No.'],
      soItm: r['SOItm'],
      soldTo: r['Sold To Party Name'] || '',
      shipTo: r['Ship To Party Name'] || '',
      shipToKey: customerIdentity(r['Ship To Party Name']),
      cityRaw,
      sourceCityRaw,
      exportDestination: exportDestination ? exportDestination.label : '',
      cityKey: resolved.key,
      coords: resolved.coords,
      cityResolved: !!resolved.coords,
      isForeign,
      thickMm, widthMm, lengthM,
      totalMT: round2(totalMT),
      planMT: round2(planMT),
      underLoadingMT: round2(underLoadingMT),
      plateWeightMT,
      plateCount,
      unitWeight,
      isODC,
      htc: r['HTC CATEGORY'] || '',
      remarks: r['Pending Dispatch Remarks'] || '',
      dchDesc: r['Dch_Desc'] || '',
      inco2: r['Inco2'] || '',
      lcDate: formatLc(lcTs),
      lcTs,
      ageing: ((v) => (v === "" || v == null || isNaN(Number(v)) ? null : Number(v)))(r["Ageing Days"]),
    };
  });
}

// Expand a row's tonnage into indivisible plate "units" for allocation across trucks.
function explodeUnits(row) {
  const units = [];
  let remaining = row.totalMT;
  for (let i = 0; i < row.plateCount; i++) {
    const isLast = i === row.plateCount - 1;
    const w = isLast ? round2(remaining) : round2(row.unitWeight);
    remaining = round2(remaining - w);
    units.push({ row, weight: Math.max(w, 0), isODC: row.isODC });
  }
  return units.filter(u => u.weight > 0);
}

// Same party spelled differently ("PES ENGINEERS PVT LTD" vs "PES ENGINEERS PVT. LTD.,") must count as ONE customer.
function customerIdentity(name) {
  return String(name || '').toUpperCase().replace(/[^A-Z0-9 ]+/g, ' ')
    .replace(/PRIVATE/g, 'PVT').replace(/LIMITED/g, 'LTD').replace(/COMPANY/g, 'CO')
    .replace(/s+/g, ' ').trim();
}

// --- Dock construction (customer + destination pool) -----------------------

function buildDocks(rows) {
  const docks = new Map();
  for (const row of rows) {
    if (row.totalMT <= 0) continue;
    const key = row.shipToKey + '||' + row.cityKey;
    if (!docks.has(key)) {
      docks.set(key, {
        key,
        customer: row.shipTo,
        customerKey: row.shipToKey,
        cityRaw: row.cityRaw,
        cityKey: row.cityKey,
        coords: row.coords,
        resolved: row.cityResolved,
        isForeign: row.isForeign,
        units: [],
        ver: 0,
      });
    }
    docks.get(key).units.push(...explodeUnits(row));
  }
  for (const d of docks.values()) {
    d.units.sort((a, b) => b.weight - a.weight);
    d.total = round2(d.units.reduce((s, u) => s + u.weight, 0));
  }
  return Array.from(docks.values());
}

function dockPending(dock) {
  return round2(dock.units.reduce((s, u) => s + u.weight, 0));
}

// --- ODC-mix feasible combination picking -----------------------------------

// Exact subset-sum picker (bin-basket / knapsack DP). Finds the subset whose total lands in
// [lo, hi] and is as FULL as possible, subject to the ODC-mix rule (pure ODC, pure NON-ODC,
// or ODC share >= ODC_MIN_SHARE). Weights are integer hundredths of an MT so the search is
// exact: unlike the old greedy orderings it finds e.g. 20.4 + 15 + 3 + 1 whenever it exists.
function reachTable(units, cap) {
  const first = new Int32Array(cap + 1).fill(-1);
  first[0] = -2;
  const w = units.map(u => Math.round(u.weight * 100));
  for (let i = 0; i < units.length; i++) {
    const wi = w[i];
    if (wi <= 0 || wi > cap) continue;
    for (let s = cap; s >= wi; s--) {
      if (first[s] === -1 && first[s - wi] !== -1) first[s] = i;
    }
  }
  return { first, w };
}

function traceTable(units, table, sum) {
  const picked = [];
  let s = sum;
  while (s > 0) {
    const i = table.first[s];
    picked.push(units[i]);
    s -= table.w[i];
  }
  return picked;
}

function pickUnitsForBand(units, lo, hi) {
  const cap = Math.round(hi * 100);
  const loI = Math.round(lo * 100);
  const odcUnits = units.filter(u => u.isODC);
  const nonUnits = units.filter(u => !u.isODC);
  const tO = reachTable(odcUnits, cap);
  const tN = reachTable(nonUnits, cap);
  // prevN[x] = largest reachable non-ODC sum <= x
  const prevN = new Int32Array(cap + 1);
  for (let x = 0; x <= cap; x++) prevN[x] = tN.first[x] !== -1 ? x : (x > 0 ? prevN[x - 1] : 0);

  let best = null;
  const total = (c) => c.o + c.n;
  const consider = (c) => { if (total(c) >= loI && (!best || total(c) > total(best))) best = c; };

  for (let o = cap; o > 0; o--) if (tO.first[o] !== -1) { consider({ o, n: 0, mode: 'ODC' }); break; }
  for (let n = cap; n > 0; n--) if (tN.first[n] !== -1) { consider({ o: 0, n, mode: 'NON ODC' }); break; }
  for (let o = 1; o <= cap; o++) {
    if (tO.first[o] === -1) continue;
    const n = prevN[Math.min(cap - o, Math.floor((2 * o) / 3))];
    if (n > 0) consider({ o, n, mode: 'MIXED' });
  }
  if (!best) return null;
  const picked = traceTable(odcUnits, tO, best.o).concat(traceTable(nonUnits, tN, best.n));
  return { picked, sum: round2(total(best) / 100), mode: best.mode };
}

function removeUnits(dock, picked) {
  dock.ver = (dock.ver || 0) + 1;
  const pickedSet = new Set(picked);
  dock.units = dock.units.filter(u => !pickedSet.has(u));
}

function addUnitToSoBreakdown(bySo, unit) {
  const so = unit.row.so + '/' + unit.row.soItm;
  if (!bySo.has(so)) {
    bySo.set(so, { mt: 0, count: 0, pieceWeight: unit.row.unitWeight, odcDimensions: [], dimensions: [], odcMt: 0 });
  }
  const entry = bySo.get(so);
  entry.mt = round2(entry.mt + unit.weight);
  if (unit.isODC) entry.odcMt = round2(entry.odcMt + unit.weight);
  entry.count += 1;
  const dimW = round2(unit.row.widthMm / 1000), dimL = round2(unit.row.lengthM);
  if (!entry.dimensions.some(d => d.widthM === dimW && d.lengthM === dimL && d.odc === !!unit.isODC)) entry.dimensions.push({ widthM: dimW, lengthM: dimL, odc: !!unit.isODC });
  if (unit.isODC) {
    const widthM = round2(unit.row.widthMm / 1000);
    const lengthM = round2(unit.row.lengthM);
    const overWidth = widthM > ODC_WIDTH_LIMIT_M;
    const overLength = lengthM > ODC_LENGTH_LIMIT_M;
    const axis = overWidth && overLength ? 'W&L' : overWidth ? 'W' : overLength ? 'L' : '';
    if (!entry.odcDimensions.some(d => d.widthM === widthM && d.lengthM === lengthM)) {
      entry.odcDimensions.push({ widthM, lengthM, axis });
    }
  }
}

// --- Main allocation ---------------------------------------------------------

// Truck packing is CPU-heavy for a large plan (tryClubbedPair rescans every remaining
// pair of docks each time it looks for a club, repeated once per truck built), so
// allocate() is async and yields to the browser's event loop every few committed
// trucks. This is purely cooperative scheduling — it changes nothing about which
// trucks get built, their order, or any tie-break — it just stops a big plan from
// freezing the tab (Chrome's "Page Unresponsive" watchdog) while it computes.
function yieldToBrowser() {
  return new Promise((resolve) => setTimeout(resolve, 0));
}

async function allocate(rawRows, cityTable, onProgress) {
  const rows = buildRows(rawRows, cityTable);
  const docks = buildDocks(rows);
  const unresolved = docks.filter(d => !d.resolved && !d.isForeign);
  const clubbable = docks.filter(d => d.resolved && !d.isForeign);
  const foreignDocks = docks.filter(d => d.isForeign);
  // Unresolved and foreign docks are excluded from cross-customer clubbing but still get
  // single-customer FTL/partial attempts on their own.
  const soloOnly = unresolved.concat(foreignDocks);

  const trucks = [];
  let truckSeq = 1;
  const totalMT0 = docks.reduce((s, d) => s + d.total, 0);

  function commitTruck(tier, participants, pickedByDock, mode) {
    const lines = [];
    let totalMT = 0;
    let odcMT = 0;
    for (const [dock, picked] of pickedByDock) {
      removeUnits(dock, picked);
      const sum = round2(picked.reduce((s, u) => s + u.weight, 0));
      totalMT = round2(totalMT + sum);
      odcMT = round2(odcMT + picked.filter(u => u.isODC).reduce((s, u) => s + u.weight, 0));
      const bySo = new Map();
      for (const u of picked) {
        addUnitToSoBreakdown(bySo, u);
      }
      lines.push({
        customer: dock.customer,
        customerKey: dock.customerKey,
        city: dock.cityRaw,
        coords: dock.coords,
        cityResolved: dock.resolved,
        soBreakdown: Array.from(bySo.entries()),
        odcMT: round2(picked.filter(u => u.isODC).reduce((s, u) => s + u.weight, 0)),
        nonOdcMT: round2(picked.filter(u => !u.isODC).reduce((s, u) => s + u.weight, 0)),
        mt: sum,
      });
    }
    trucks.push({
      id: 'T' + String(truckSeq++).padStart(3, '0'),
      tier: tier.id,
      tierLabel: tier.label,
      suggestion: tier.suggestion,
      customerCount: new Set(participants.map(d => d.customerKey)).size,
      lines,
      totalMT,
      odcMT,
      nonOdcMT: round2(totalMT - odcMT),
      odcShare: totalMT > 0 ? round2((odcMT / totalMT) * 100) : 0,
      fillPct: round2((totalMT / tier.target) * 100),
      mode,
    });
  }

  // Neighbour lists: pairs of docks (different customers) within CLUB_RADIUS_KM.
  const neighbours = new Map(clubbable.map(d => [d, []]));
  for (let i = 0; i < clubbable.length; i++) {
    for (let j = i + 1; j < clubbable.length; j++) {
      const a = clubbable[i], b = clubbable[j];
      if (a.customerKey === b.customerKey) continue;
      const dist = haversineKm(a.coords, b.coords);
      if (dist <= CLUB_RADIUS_KM) neighbours.get(a).push({ other: b, dist });
    }
  }
  const cache = new Map();
  function cached(key, ver, compute) {
    const hit = cache.get(key);
    if (hit && hit.ver === ver) return hit.val;
    const val = compute();
    cache.set(key, { ver, val });
    return val;
  }

  // Global best-fit over every single dock and every valid 2-dock club for this tier: the
  // fullest candidate wins (ties: single over club, then shorter distance). Results are
  // cached per dock/pair and recomputed only when a dock's units changed.
  function bestCandidate(tier) {
    let best = null;
    const [lo, hi] = tier.band;
    const consider = (c) => {
      if (!best || c.res.sum > best.res.sum + 1e-9 ||
        (Math.abs(c.res.sum - best.res.sum) <= 1e-9 && (c.docks.length < best.docks.length || (c.docks.length === best.docks.length && c.dist < best.dist)))) best = c;
    };
    for (const dock of clubbable.concat(soloOnly)) {
      if (dockPending(dock) < lo) continue;
      const res = cached(tier.id + '|' + dock.key, dock.ver, () => pickUnitsForBand(dock.units, lo, hi));
      if (res) consider({ docks: [dock], picks: [res.picked], res, dist: 0 });
    }
    for (const [a, list] of neighbours) {
      const pa = dockPending(a);
      if (pa <= 0) continue;
      for (const { other: b, dist } of list) {
        const pb = dockPending(b);
        if (pb <= 0 || pa + pb < lo) continue;
        const res = cached(tier.id + '|' + a.key + '|' + b.key, a.ver + ':' + b.ver, () => {
          const r = pickUnitsForBand(a.units.concat(b.units), lo, hi);
          if (!r) return null;
          const setA = new Set(a.units);
          const pickedA = r.picked.filter(u => setA.has(u));
          const pickedB = r.picked.filter(u => !setA.has(u));
          return pickedA.length && pickedB.length ? { ...r, pickedA, pickedB } : null;
        });
        if (res) consider({ docks: [a, b], picks: [res.pickedA, res.pickedB], res, dist });
      }
    }
    return best;
  }

  async function runTier(tier) {
    let lastYield = performance.now();
    for (;;) {
      const c = bestCandidate(tier);
      if (!c) break;
      const mode = c.docks.length > 1 ? c.res.mode + ' (clubbed, ' + round2(c.dist) + ' km)' : c.res.mode;
      commitTruck(tier, c.docks, c.docks.map((d, i) => [d, c.picks[i]]), mode);
      // Yield on elapsed time (not truck count) so one slow truck can't freeze the tab.
      if (performance.now() - lastYield > 30) {
        if (onProgress) onProgress(1 - docks.reduce((s, d) => s + d.units.reduce((t, u) => t + u.weight, 0), 0) / (totalMT0 || 1), trucks.length);
        await yieldToBrowser(); lastYield = performance.now();
      }
    }
  }

  for (const tier of TRUCK_TIERS) await runTier(tier);

  // Whatever remains is LTL — manual clubbing worklist, grouped by proximity for convenience.
  const ltl = [];
  for (const dock of docks) {
    const pending = dockPending(dock);
    if (pending > 0.005) {
      const bySo = new Map();
      for (const u of dock.units) {
        addUnitToSoBreakdown(bySo, u);
      }
      ltl.push({
        customer: dock.customer,
        customerKey: dock.customerKey,
        city: dock.cityRaw,
        cityResolved: dock.resolved,
        isForeign: dock.isForeign,
        pendingMT: pending,
        odcMT: round2(dock.units.reduce((s, u) => s + (u.isODC ? u.weight : 0), 0)),
        nonOdcMT: round2(dock.units.reduce((s, u) => s + (!u.isODC ? u.weight : 0), 0)),
        coords: dock.coords,
        soBreakdown: Array.from(bySo.entries()),
      });
    }
  }
  // Group LTL rows into nearby clusters (<=100km) purely for display/manual-clubbing suggestion.
  const ltlClusters = clusterByProximity(ltl.filter(l => l.cityResolved));
  const ltlUnresolved = ltl.filter(l => !l.cityResolved);

  return {
    rows,
    trucks,
    ltl,
    ltlClusters,
    ltlUnresolved,
    totalMT: round2(rows.reduce((s, r) => s + r.totalMT, 0)),
  };
}

function clusterByProximity(items) {
  const remaining = items.slice();
  const clusters = [];
  while (remaining.length) {
    const seed = remaining.shift();
    const cluster = [seed];
    for (let i = remaining.length - 1; i >= 0; i--) {
      if (haversineKm(seed.coords, remaining[i].coords) <= CLUB_RADIUS_KM) {
        cluster.push(remaining[i]);
        remaining.splice(i, 1);
      }
    }
    clusters.push(cluster);
  }
  return clusters.sort((a, b) => b.length - a.length);
}

/* ── format.js (ported from truck-dashboard/src/lib/format.js) ─────────────────────────── */
function fmt(n) { return Number(n).toLocaleString('en-IN', { minimumFractionDigits: 2, maximumFractionDigits: 2 }); }
function money(value) { return value === null || value === undefined ? '—' : 'Rs ' + Number(value).toLocaleString('en-IN', { minimumFractionDigits: 2, maximumFractionDigits: 2 }); }
const rateText = money;
function toCsv(rows) {
  return rows.map(r => r.map(cell => {
    const s = String(cell ?? '');
    return /[",\n]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s;
  }).join(',')).join('\n');
}
function odcDimensionEntries(value) {
  return (value.odcDimensions || []).map(d => 'W ' + fmt(d.widthM) + ' m x L ' + fmt(d.lengthM) + ' m');
}

// Dimensions of every plate on an SO line (ODC and non-ODC), flagged so the ODC ones can be highlighted.
function allDimensionEntries(value) {
  const list = value.dimensions || (value.odcDimensions || []).map(d => ({ ...d, odc: true }));
  return list.map(d => ({ text: 'W ' + fmt(d.widthM) + ' m x L ' + fmt(d.lengthM) + ' m', odc: !!d.odc }));
}
function dimensionText(dimensions) {
  return dimensions.length ? dimensions.map(d => 'W ' + fmt(d.widthM) + ' m x L ' + fmt(d.lengthM) + ' m').join(' / ') : '—';
}

/* ── freight.js (ported from truck-dashboard/src/lib/freight.js) ─────────────────────────── */
// Freight-rate / ODC / RTO / SOB business logic — ported near-verbatim from the legacy
// vanilla index.html script. No DOM access; XLSX workbook objects go in, plain JS out.
// Kept as close as possible to the legacy implementation described in HANDOFF_CONTEXT.md
// (destination/state/zone resolution, ODC+RTO surcharge bands, nearest-city rate
// interpolation, SOB workbook shape) — do not "clean up" the business rules here.
var XLSX = window.XLSX; // SheetJS loaded from CDN in Truck-Dashboard.html
const ZONE_STATES = {
  NORTH: ['DELHI', 'NEW DELHI', 'HARYANA', 'UTTARAKHAND', 'UTTARKHAND', 'PUNJAB', 'HIMACHAL PRADESH', 'JAMMU KASHMIR', 'JAMMU AND KASHMIR', 'NEPAL', 'BHUTAN'],
  SOUTH: ['KARNATAKA', 'TAMIL NADU', 'TAMILNADU', 'KERALA', 'ANDHRA PRADESH', 'TELANGANA', 'GOA'],
  WEST: ['MAHARASHTRA', 'MAHARASTRA', 'GUJARAT', 'RAJASTHAN'],
  EAST: ['BIHAR', 'JHARKHAND', 'WEST BENGAL', 'SIKKIM', 'ASSAM', 'ARUNACHAL PRADESH', 'MANIPUR', 'MEGHALAYA', 'MIZORAM', 'NAGALAND', 'TRIPURA'],
  EXPORT: ['UAE', 'BELGIUM', 'CANADA', 'CZECH REPUBLIC', 'SWITZERLAND', 'POLAND', 'DENMARK', 'ESTONIA', 'SOUTH KOREA', 'UK', 'USA', 'GERMANY', 'HONG KONG'],
  CENTER: ['MADHYA PRADESH', 'ODISHA', 'ORISSA', 'CHHATTISGARH', 'CHATTISGARH'],
};
const NEAREST_RATE_RADIUS_KM = 100;
const SOB_STORAGE_KEY = 'truckDashboard.transporterSOB';
function normalizedKey(value) {
  return String(value || '').toUpperCase().replace(/[^A-Z0-9]+/g, ' ').replace(/\s+/g, ' ').trim();
}
function compactKey(value) { return normalizedKey(value).replace(/ /g, ''); }
function zoneForState(state) {
  const key = normalizedKey(state);
  for (const [zone, states] of Object.entries(ZONE_STATES)) {
    if (states.includes(key)) return zone.charAt(0) + zone.slice(1).toLowerCase();
  }
  return '';
}

function rateField(row, names) {
  const keys = Object.keys(row);
  const exact = keys.find(key => names.some(name => normalizedKey(key) === normalizedKey(name)));
  if (exact) return row[exact];
  const partial = keys.find(key => names.some(name => normalizedKey(key).includes(normalizedKey(name))));
  return partial ? row[partial] : '';
}
function numberValue(value) {
  if (value === null || value === undefined || value === '') return null;
  const parsed = Number(String(value).replace(/[^0-9.-]/g, ''));
  return Number.isFinite(parsed) ? parsed : null;
}

function parseRange(value) {
  const text = String(value || '').trim();
  const numbers = text.match(/\d+(?:\.\d+)?/g);
  if (!numbers || !numbers.length) return null;
  const first = Number(numbers[0]);
  const second = numbers.length > 1 ? Number(numbers[1]) : first;
  if (/^(>|above|over|and above)\b|^>\s*/i.test(text)) return { min: first, max: Infinity };
  if (/^(<|below|up ?to)\b|^<\s*/i.test(text)) return { min: 0, max: first };
  return { min: numbers.length > 1 ? Math.min(first, second) : 0, max: Math.max(first, second) };
}

function rangeContains(value, range) {
  if (!range) return false;
  if (range.max === Infinity) return value > range.min + 1e-9;
  return value >= range.min - 1e-9 && value <= range.max + 1e-9;
}

function parseOdcBands(workbook) {
  const sheetName = workbook.SheetNames.find(name => /odc/i.test(name)) || workbook.SheetNames.find(name => /charge/i.test(name));
  if (!sheetName) return { lengthBands: [], widthBands: [] };
  const matrix = XLSX.utils.sheet_to_json(workbook.Sheets[sheetName], { header: 1, defval: '' });
  let headerRow = -1;
  let lengthRangeCol = -1, lengthChargeCol = -1, widthRangeCol = -1, widthChargeCol = -1;
  for (let i = 0; i < Math.min(matrix.length, 15); i++) {
    const cells = matrix[i].map(value => normalizedKey(value));
    const lengthIdx = cells.findIndex(c => c.includes('LENGTH'));
    const widthIdx = cells.findIndex(c => c.includes('WIDTH'));
    if (lengthIdx < 0 && widthIdx < 0) continue;
    headerRow = i;
    if (lengthIdx >= 0) {
      lengthRangeCol = lengthIdx;
      for (let c = lengthIdx + 1; c < cells.length; c++) { if (cells[c].includes('CHARGE') || cells[c].includes('RATE')) { lengthChargeCol = c; break; } }
    }
    if (widthIdx >= 0) {
      widthRangeCol = widthIdx;
      for (let c = widthIdx + 1; c < cells.length; c++) { if (cells[c].includes('CHARGE') || cells[c].includes('RATE')) { widthChargeCol = c; break; } }
    }
    break;
  }
  const lengthBands = [];
  const widthBands = [];
  if (headerRow >= 0) {
    for (let r = headerRow + 1; r < matrix.length; r++) {
      const row = matrix[r];
      if (lengthRangeCol >= 0 && lengthChargeCol >= 0) {
        const range = parseRange(row[lengthRangeCol]);
        const charge = numberValue(row[lengthChargeCol]);
        if (range && charge !== null) lengthBands.push({ min: range.min, max: range.max, charge });
      }
      if (widthRangeCol >= 0 && widthChargeCol >= 0) {
        const range = parseRange(row[widthRangeCol]);
        const charge = numberValue(row[widthChargeCol]);
        if (range && charge !== null) widthBands.push({ min: range.min, max: range.max, charge });
      }
    }
  }
  return { lengthBands, widthBands };
}

function parseRtoTable(workbook) {
  const sheetName = workbook.SheetNames.find(name => /rto/i.test(name));
  if (!sheetName) return null;
  const matrix = XLSX.utils.sheet_to_json(workbook.Sheets[sheetName], { header: 1, defval: '' });
  let headerRow = -1, stateCol = 0, lengthCol = -1, widthCol = -1;
  for (let i = 0; i < Math.min(matrix.length, 10); i++) {
    const cells = matrix[i].map(value => normalizedKey(value));
    const lengthIdx = cells.findIndex(c => c.includes('LENGTH'));
    const widthIdx = cells.findIndex(c => c.includes('WIDTH'));
    if (lengthIdx < 0 || widthIdx < 0) continue;
    const stateIdx = cells.findIndex(c => c.includes('STATE'));
    headerRow = i;
    lengthCol = lengthIdx;
    widthCol = widthIdx;
    if (stateIdx >= 0) stateCol = stateIdx;
    break;
  }
  if (headerRow < 0) return null;
  let lengthThreshold = 12.0, widthThreshold = 2.5;
  let dataStart = headerRow + 1;
  for (let i = headerRow + 1; i < Math.min(matrix.length, headerRow + 4); i++) {
    const lengthText = String(matrix[i][lengthCol] || '').trim();
    const widthText = String(matrix[i][widthCol] || '').trim();
    if (/^>/.test(lengthText) || /^>/.test(widthText)) {
      const lengthRange = parseRange(lengthText);
      const widthRange = parseRange(widthText);
      if (lengthRange) lengthThreshold = lengthRange.min;
      if (widthRange) widthThreshold = widthRange.min;
      dataStart = i + 1;
      break;
    }
  }
  const states = new Map();
  for (let r = dataStart; r < matrix.length; r++) {
    const row = matrix[r];
    const stateName = String(row[stateCol] || '').trim();
    if (!stateName || stateName === '-') continue;
    const lengthCharge = numberValue(row[lengthCol]) || 0;
    const widthCharge = numberValue(row[widthCol]) || 0;
    states.set(normalizedKey(stateName), { lengthCharge, widthCharge });
  }
  return { states, lengthThreshold, widthThreshold };
}

// Export destinations (shown as Zone "Export", State = country).
const FOREIGN_COUNTRY = {
  DUBAI: 'UAE', ANTWERP: 'Belgium', CANADA: 'Canada', VANCOUVER: 'Canada', PRAHA: 'Czech Republic', PRAGUE: 'Czech Republic',
  LUGANO: 'Switzerland', GDANSK: 'Poland', GDYNIA: 'Poland', FREDERICIA: 'Denmark', MUUGA: 'Estonia', YEONSU: 'South Korea',
  SEOUL: 'South Korea', 'SEOUL REPUBLIC OF KOREA': 'South Korea', LIVERPOOL: 'UK', ARIZONA: 'USA', DUISBURG: 'Germany', 'CONNAUGHT ROAD': 'Hong Kong',
};
const foreignCountry = (destination) => FOREIGN_COUNTRY[normalizedKey(destination)] || '';

function stateHintForDestination(destination) {
  const key = normalizedKey(destination);
  if (key.includes('PARADEEP') || key.includes('PARADIP') || key.includes('BHUBANESWAR') || key.includes('ANGUL')) return 'Odisha';
  if (key.includes('DANKUNI')) return 'West Bengal';
  if (key.includes('VIZAG') || key.includes('VISAKHAPATNAM')) return 'Andhra Pradesh';
  return '';
}
function round2ui(n) { return Math.round(n * 100) / 100; }
function buildFreightRateModel(rows, workbook) {
  const records = rows.map(row => {
    const destination = String(rateField(row, ['Destination', 'Destination City', 'Ship To Party City', 'City', 'Location', 'Port']) || '').trim();
    const state = String(rateField(row, ['State', 'Destination State']) || '').trim();
    const zone = String(rateField(row, ['Zone', 'Region']) || zoneForState(state)).trim();
    const distanceFromAngul = numberValue(rateField(row, ['Distance from Angul (KM)', 'Distance from Angul', 'Distance (KM)', 'Distance']));
    const transporterRate = numberValue(rateField(row, ['Transporter Freight', 'Paid To Transporter', 'Transporter Rate', 'Freight Paid', 'Freight Rate', 'Cost To Serve Rate']));
    const marketingRate = numberValue(rateField(row, ['Marketing Freight', 'Marketing Recovery', 'Marketing Rate', 'Recovery Freight Rate', 'Recovery Rate', 'Recovery']));
    const odcRate = numberValue(rateField(row, ['ODC Charges', 'ODC Charge', 'ODC Freight', 'ODC Rs/MT', 'ODC Rate', 'ODC']));
    const rtoRate = numberValue(rateField(row, ['RTO Charges', 'RTO Charge', 'RTO Rate', 'RTO']));
    return {
      destination, destinationKey: compactKey(destination), state, stateKey: normalizedKey(state),
      zone: zone || zoneForState(state), transporterRate, marketingRate, odcRate, rtoRate, distanceFromAngul,
    };
  }).filter(row => row.destination || row.state || row.zone || row.transporterRate !== null || row.marketingRate !== null || row.odcRate !== null || row.rtoRate !== null);

  function mergeBy(recordsToMerge, keyField) {
    const merged = new Map();
    recordsToMerge.forEach(record => {
      const key = record[keyField];
      if (!key) return;
      const existing = merged.get(key);
      if (!existing) { merged.set(key, { ...record }); return; }
      ['destination', 'state', 'zone', 'transporterRate', 'marketingRate', 'odcRate', 'rtoRate', 'distanceFromAngul'].forEach(field => {
        if ((existing[field] === '' || existing[field] === null || existing[field] === undefined) && record[field] !== '' && record[field] !== null && record[field] !== undefined) existing[field] = record[field];
      });
    });
    return merged;
  }
  return {
    records,
    odcBands: parseOdcBands(workbook),
    rtoTable: parseRtoTable(workbook),
    byDestination: mergeBy(records, 'destinationKey'),
    byState: mergeBy(records, 'stateKey'),
    byZone: mergeBy(records.map(record => ({ ...record, zoneKey: normalizedKey(record.zone) })), 'zoneKey'),
  };
}

// --- helpers that need the city table + rate model together ----------------
function odcChargeForDimensions(freightRateModel, dimensions) {
  const bands = freightRateModel && freightRateModel.odcBands;
  if (!bands || (!bands.lengthBands.length && !bands.widthBands.length) || !dimensions.length) return null;
  const maxLength = Math.max(...dimensions.map(d => d.lengthM));
  const maxWidth = Math.max(...dimensions.map(d => d.widthM));
  const lengthBand = bands.lengthBands.find(b => rangeContains(maxLength, b));
  const widthBand = bands.widthBands.find(b => rangeContains(maxWidth, b));
  if (!lengthBand && !widthBand) return null;
  return Math.round(((lengthBand ? lengthBand.charge : 0) + (widthBand ? widthBand.charge : 0)) * 100) / 100;
}
function rtoChargeForDimensions(freightRateModel, state, dimensions) {
  const table = freightRateModel && freightRateModel.rtoTable;
  if (!table || !dimensions.length) return null;
  const maxLength = Math.max(...dimensions.map(d => d.lengthM));
  const maxWidth = Math.max(...dimensions.map(d => d.widthM));
  const exceedsLength = maxLength > table.lengthThreshold;
  const exceedsWidth = maxWidth > table.widthThreshold;
  if (!exceedsLength && !exceedsWidth) return 0;
  const entry = table.states.get(normalizedKey(state));
  if (!entry) return null;
  let charge = 0;
  if (exceedsLength) charge += entry.lengthCharge;
  if (exceedsWidth) charge += entry.widthCharge;
  return charge;
}

function nearestRateInterpolation(freightRateModel, cityTable, destination, hintState = '') {
  const ANGUL_COORDS = cityTable && cityTable['ANGUL'];
  if (!freightRateModel || !ANGUL_COORDS) return null;
  const resolved = resolveCity(destination, cityTable);
  if (!resolved.coords) return null;
  const targetDistanceFromAngul = haversineKm(ANGUL_COORDS, resolved.coords);

  let best = null, bestKm = Infinity;
  for (const record of freightRateModel.byDestination.values()) {
    if (record.transporterRate === null || record.transporterRate === undefined) continue;
    if (!record.distanceFromAngul || record.distanceFromAngul <= 0) continue;
    const cityResolved = resolveCity(record.destination, cityTable);
    if (!cityResolved.coords) continue;
    // Guard against namesakes (two places called BALANAGAR): wrong state, or a road distance that cannot match where the name resolved.
    if (hintState && record.state && normalizedKey(record.state) !== normalizedKey(hintState)) continue;
    const straightFromAngul = haversineKm(ANGUL_COORDS, cityResolved.coords);
    if (record.distanceFromAngul < straightFromAngul * 0.8 || record.distanceFromAngul > straightFromAngul * 2) continue;
    const km = haversineKm(resolved.coords, cityResolved.coords);
    if (km <= NEAREST_RATE_RADIUS_KM && km < bestKm) { bestKm = km; best = record; }
  }
  if (!best) return null;

  const perKmRate = best.transporterRate / best.distanceFromAngul;
  const estimatedRate = round2ui(perKmRate * targetDistanceFromAngul);
  return {
    state: best.state, zone: best.zone,
    transporterRate: estimatedRate, marketingRate: best.marketingRate, odcRate: best.odcRate, rtoRate: best.rtoRate,
    estimated: true, referenceCity: best.destination, kmFromReference: round2ui(bestKm),
    estimatedDistanceFromAngul: round2ui(targetDistanceFromAngul),
  };
}
function lookupFreight(freightRateModel, cityTable, destination) {
  const country = foreignCountry(destination);
  if (country) return { state: country, zone: zoneForState(country), transporterRate: null, marketingRate: null, odcRate: null, rtoRate: null };
  if (!freightRateModel) {
    const hint = stateHintForDestination(destination);
    return { state: hint, zone: zoneForState(hint), transporterRate: null, marketingRate: null, odcRate: null, rtoRate: null };
  }
  const destinationKey = compactKey(destination);
  const hintState = stateHintForDestination(destination);
  let record = freightRateModel.byDestination.get(destinationKey);
  if (!record && destinationKey.length >= 4) {
    // Whole-word containment only ("SPSR NELLORE DISTRICT" ~ "NELLORE"); raw substrings wrongly matched VISAKHAPATNAM to PATNA (Bihar).
    const padded = ' ' + normalizedKey(destination) + ' ';
    const fuzzy = Array.from(freightRateModel.byDestination.values()).filter(candidate => {
      if (!candidate.destinationKey) return false;
      const other = ' ' + normalizedKey(candidate.destination) + ' ';
      if (!padded.includes(other) && !other.includes(padded)) return false;
      return !hintState || !candidate.state || normalizedKey(candidate.state) === normalizedKey(hintState);
    });
    fuzzy.sort((a, b) => b.destinationKey.length - a.destinationKey.length);
    record = fuzzy[0];
  }
  if (!record) {
    const interpolated = nearestRateInterpolation(freightRateModel, cityTable, destination, hintState);
    if (interpolated) return interpolated;
  }
  const matchedDestination = !!record;
  record = record || freightRateModel.byState.get(normalizedKey(hintState)) || freightRateModel.byZone.get(normalizedKey(zoneForState(hintState)));
  if (!record) return { state: hintState, zone: zoneForState(hintState), transporterRate: null, marketingRate: null, odcRate: null, rtoRate: null };
  const state = matchedDestination ? record.state || hintState : hintState || record.state;
  return { state, zone: zoneForState(state) || record.zone, transporterRate: record.transporterRate, marketingRate: record.marketingRate, odcRate: record.odcRate, rtoRate: record.rtoRate };
}
function shipmentDimensions(line) {
  const dimensions = [];
  line.soBreakdown.forEach(([, value]) => (value.odcDimensions || []).forEach(dimension => {
    if (!dimensions.some(item => item.widthM === dimension.widthM && item.lengthM === dimension.lengthM)) dimensions.push(dimension);
  }));
  return dimensions;
}
function totalCostForShipment(freightRateModel, cityTable, destination, shipment, mt) {
  const rate = lookupFreight(freightRateModel, cityTable, destination);
  const dimensions = shipmentDimensions(shipment);
  const isODC = shipment.odcMT > 0.005;
  const odcRate = isODC ? (odcChargeForDimensions(freightRateModel, dimensions) ?? rate.odcRate) : 0;
  const rtoRate = isODC ? rtoChargeForDimensions(freightRateModel, rate.state, dimensions) : 0;
  const totalRate = rate.transporterRate === null || odcRate === null || rtoRate === null ? null : rate.transporterRate + odcRate + rtoRate;
  return totalRate === null ? null : mt * totalRate;
}

// Per-shipment analysis rows — used by Cost Analysis, Insights, and SOB tabs alike.
function analysisRows(freightRateModel, cityTable, result) {
  const rows = [];
  result.trucks.forEach(truck => truck.lines.forEach(line => {
    const rate = lookupFreight(freightRateModel, cityTable, line.city);
    const dimensions = shipmentDimensions(line);
    const isODC = line.odcMT > 0.005;
    const matrixCharge = odcChargeForDimensions(freightRateModel, dimensions);
    const odcRate = isODC ? (matrixCharge ?? rate.odcRate) : 0;
    const rtoRate = isODC ? rtoChargeForDimensions(freightRateModel, rate.state, dimensions) : 0;
    const capacity = truck.tier === '40MT' ? 40 : truck.tier === '32MT' ? 32 : 0;
    const deadFreightTotal = capacity > 0 ? Math.max(0, capacity - truck.totalMT) : 0;
    const deadFreightMT = truck.totalMT > 0 ? deadFreightTotal * (line.mt / truck.totalMT) : 0;
    const chargeableMT = line.mt + deadFreightMT;
    const totalCostRate = rate.transporterRate === null || odcRate === null || rtoRate === null ? null : rate.transporterRate + odcRate + rtoRate;
    const recoveryBase = rate.marketingRate === null || odcRate === null || rtoRate === null ? null : rate.marketingRate + odcRate + rtoRate;
    const recoveryRate = recoveryBase === null ? null : isODC ? recoveryBase + (recoveryBase * 0.03) : rate.marketingRate;
    const transporterCost = totalCostRate === null ? null : chargeableMT * totalCostRate;
    const deadFreightAmount = totalCostRate === null ? null : deadFreightMT * totalCostRate;
    const recovery = recoveryRate === null ? null : chargeableMT * recoveryRate;
    rows.push({
      truck: truck.id, priority: truck.tierLabel, customer: line.customer, destination: line.city,
      state: rate.state || 'Unknown', zone: rate.zone || 'Unknown', dimensions, mt: line.mt, deadFreightMT, deadFreightAmount,
      chargeableMT, transporterRate: rate.transporterRate, odcRate, rtoRate, totalCostRate, transporterCost,
      marketingRate: rate.marketingRate, recoveryRate, recovery,
      variance: transporterCost === null || recovery === null ? null : recovery - transporterCost,
      estimated: !!rate.estimated, referenceCity: rate.referenceCity, kmFromReference: rate.kmFromReference,
    });
  }));
  return rows;
}

// --- Transporter SOB workbook parsing ---------------------------------
// Real shape (Sheet1 of "Transporter SOB for Plate.xlsx"): Sr | State | <transporter
// name columns...> | Total. Each state row has %, blank for transporters with no
// allocation, Total ~= 100%.
function parseSobWorkbook(workbook) {
  const sheetName = workbook.SheetNames.find(n => /sob/i.test(n)) || workbook.SheetNames[0];
  const sheet = workbook.Sheets[sheetName];
  const matrix = XLSX.utils.sheet_to_json(sheet, { header: 1, defval: '' });
  if (!matrix.length) throw new Error('No rows found in "' + sheetName + '".');
  const header = matrix[0].map(h => String(h || '').trim());
  const stateCol = header.findIndex(h => /^state$/i.test(h));
  if (stateCol === -1) throw new Error('Could not find a "State" column in "' + sheetName + '".');
  const transporterCols = [];
  header.forEach((h, idx) => {
    if (idx === stateCol) return;
    if (!h) return;
    if (/^sr\.?$/i.test(h) || /^total$/i.test(h)) return;
    transporterCols.push({ idx, name: h });
  });
  const states = {};
  for (let r = 1; r < matrix.length; r++) {
    const row = matrix[r];
    const stateLabel = String(row[stateCol] || '').trim();
    if (!stateLabel) continue;
    const key = stateLabel.toUpperCase();
    const transporters = {};
    transporterCols.forEach(col => {
      const raw = row[col.idx];
      if (raw === '' || raw === undefined || raw === null) return;
      let pct = typeof raw === 'number' ? raw : parseFloat(String(raw).replace('%', ''));
      if (isNaN(pct)) return;
      if (pct > 0 && pct <= 1 && String(raw).includes('%') === false && typeof raw === 'number') pct = pct * 100; // fraction stored as 0.15
      transporters[col.name] = Math.round(pct * 100) / 100;
    });
    states[key] = { label: stateLabel, transporters };
  }
  const transporterNames = [...new Set(transporterCols.map(c => c.name))];
  return { states, transporters: transporterNames, sheetName };
}
function sobStateEntry(sobData, stateName) {
  if (!sobData || !stateName) return null;
  return sobData.states[String(stateName).trim().toUpperCase()] || null;
}

// SOB-aware transporter suggestion per truck — wraps engine output, never re-packs
// trucks. Biases toward whichever transporter is furthest below its state SOB target.
function computeSobSuggestions(sobData, freightRateModel, cityTable, result) {
  if (!sobData || !result || !result.trucks.length) return [];
  const realizedMtByStateTransporter = new Map();
  const realizedMtByState = new Map();
  function pctFor(state, transporter) {
    const already = realizedMtByStateTransporter.get(state + '||' + transporter) || 0;
    const stateTotal = realizedMtByState.get(state) || 0;
    return stateTotal > 0 ? round2ui((already / stateTotal) * 100) : 0;
  }
  return result.trucks.map(truck => {
    const statesOnTruck = [...new Set(truck.lines.map(l => lookupFreight(freightRateModel, cityTable, l.city).state || 'Unknown'))];
    const primaryState = statesOnTruck[0] || 'Unknown';
    const entry = sobStateEntry(sobData, primaryState);
    let suggested = 'Unassigned', targetPct = null;
    if (entry && Object.keys(entry.transporters).length) {
      let best = null, bestGap = -Infinity;
      Object.entries(entry.transporters).forEach(([name, target]) => {
        const realizedPct = pctFor(primaryState, name);
        const gap = target - realizedPct;
        if (gap > bestGap) { bestGap = gap; best = name; targetPct = target; }
      });
      suggested = best || 'Unassigned';
    }
    realizedMtByStateTransporter.set(primaryState + '||' + suggested, (realizedMtByStateTransporter.get(primaryState + '||' + suggested) || 0) + truck.totalMT);
    realizedMtByState.set(primaryState, (realizedMtByState.get(primaryState) || 0) + truck.totalMT);
    truck.sobSuggestedTransporter = suggested; // stashed for the Business Insights tab, same as legacy
    const realizedAfter = pctFor(primaryState, suggested);
    return { truckId: truck.id, states: statesOnTruck, mt: truck.totalMT, suggested, targetPct, realizedAfter };
  });
}

/* ── capacity.js (ported from truck-dashboard/src/lib/capacity.js) ─────────────────────────── */
// Unloading capacity of a customer site, derived from observed closed trips.
// Throughput = trips (and MT) per day over the observed window; "on site" load = average trucks
// inside the gate (sum of dwell hours / window hours, Little's law); peak = most trucks inside at once.
// Capacity @ standard = trucks/day the same average on-site load would clear if each truck left within `tat` hours.
const HOUR_MS = 3600000;
function capacity(rows, tat) {
  const n = rows.length;
  if (!n) return null;
  const start = Math.min(...rows.map((r) => r.entry.getTime()));
  const end = Math.max(...rows.map((r) => r.exit.getTime()));
  const spanH = Math.max(24, (end - start) / HOUR_MS);
  const sumH = rows.reduce((s, r) => s + r.hours, 0);
  const qty = rows.reduce((s, r) => s + r.qty, 0);
  const ev = [];
  rows.forEach((r) => { ev.push([r.entry.getTime(), 1], [r.exit.getTime(), -1]); });
  ev.sort((a, b) => a[0] - b[0] || a[1] - b[1]); // exits before entries at the same instant
  let cur = 0, peak = 0;
  ev.forEach(([, d]) => { cur += d; if (cur > peak) peak = cur; });
  const trucksPerDay = n / (spanH / 24);
  const avgOnSite = sumH / spanH;
  const mtPerTruck = qty / n;
  const stdTrucksPerDay = (avgOnSite * 24) / tat;
  return {
    n, qty, spanDays: spanH / 24, trucksPerDay, mtPerDay: qty / (spanH / 24), mtPerTruck,
    avgDwell: sumH / n, avgOnSite, peak,
    mtPerOnSiteHour: sumH ? qty / sumH : 0,
    stdTrucksPerDay, stdMtPerDay: stdTrucksPerDay * mtPerTruck,
    gap: trucksPerDay ? stdTrucksPerDay / trucksPerDay : 0,
  };
}

/* ── columnResize.js (ported from truck-dashboard/src/lib/columnResize.js) ─────────────────────────── */
// Excel-style column sizing for every table: drag a header divider to resize,
// double-click it to auto-fit the column to its longest cell. Uses event delegation so it
// works for any <table> React renders, with no per-table code.
const EDGE = 6;
const MIN_W = 36;

function edgeHit(th, clientX) {
  const r = th.getBoundingClientRect();
  return r.right - clientX <= EDGE && r.right - clientX >= -2;
}

// Switch the table to fixed layout, pinning every column at its current width, so one column can change independently.
function freeze(table) {
  if (table.dataset.frozen) return;
  const ths = [...table.tHead.rows[table.tHead.rows.length - 1].cells];
  const widths = ths.map((th) => th.getBoundingClientRect().width);
  ths.forEach((th, i) => { th.style.width = widths[i] + 'px'; th.style.minWidth = '0'; });
  table.style.tableLayout = 'fixed';
  table.style.minWidth = '0';
  table.style.width = widths.reduce((a, b) => a + b, 0) + 'px';
  table.dataset.frozen = '1';
}

function setWidth(table, th, w) {
  const w0 = th.getBoundingClientRect().width;
  const total = table.getBoundingClientRect().width;
  th.style.width = w + 'px';
  table.style.width = total - w0 + w + 'px';
}

function autoFit(table, th) {
  const col = th.cellIndex;
  setWidth(table, th, 1); // collapse first: scrollWidth can't report less than the current box width
  let max = th.scrollWidth;
  [...table.tBodies].forEach((tb) => [...tb.rows].forEach((row) => {
    const cell = row.cells[col];
    if (cell && cell.colSpan === 1 && row.cells.length > col) max = Math.max(max, cell.scrollWidth);
  }));
  setWidth(table, th, Math.max(MIN_W, Math.ceil(max) + 2));
}
function installColumnResize() {
  let drag = null;

  const onMove = (e) => {
    if (drag) {
      setWidth(drag.table, drag.th, Math.max(MIN_W, drag.w0 + e.clientX - drag.x0));
      return;
    }
    const th = e.target.closest?.('thead th');
    document.body.style.cursor = th && edgeHit(th, e.clientX) ? 'col-resize' : '';
  };
  const onDown = (e) => {
    const th = e.target.closest?.('thead th');
    if (!th || !edgeHit(th, e.clientX) || e.button !== 0) return;
    const table = th.closest('table');
    freeze(table);
    drag = { table, th, x0: e.clientX, w0: th.getBoundingClientRect().width };
    document.body.classList.add('col-resizing');
    e.preventDefault();
  };
  const onUp = () => {
    if (!drag) return;
    drag = null;
    document.body.classList.remove('col-resizing');
  };
  const onDbl = (e) => {
    const th = e.target.closest?.('thead th');
    if (!th || !edgeHit(th, e.clientX)) return;
    const table = th.closest('table');
    freeze(table);
    autoFit(table, th);
    e.preventDefault();
  };
  const onClickCapture = (e) => { // a divider drag/double-click must not trigger header click-sorting
    const th = e.target.closest?.('thead th');
    if (th && edgeHit(th, e.clientX)) { e.stopPropagation(); e.preventDefault(); }
  };

  document.addEventListener('mousemove', onMove);
  document.addEventListener('mousedown', onDown);
  document.addEventListener('mouseup', onUp);
  document.addEventListener('dblclick', onDbl);
  document.addEventListener('click', onClickCapture, true);
  return () => {
    document.removeEventListener('mousemove', onMove);
    document.removeEventListener('mousedown', onDown);
    document.removeEventListener('mouseup', onUp);
    document.removeEventListener('dblclick', onDbl);
    document.removeEventListener('click', onClickCapture, true);
  };
}

/* ── cityOverrides.js (ported from truck-dashboard/src/lib/cityOverrides.js) ─────────────────────────── */
// Destinations the user resolved by hand (city name or lat/lng), kept in this browser and merged into the city table.
const KEY = 'truck-dashboard-city-overrides';
function loadCityOverrides(table) {
  try {
    const saved = JSON.parse(localStorage.getItem(KEY) || '{}');
    for (const k of Object.keys(saved)) if (Array.isArray(saved[k])) table[k] = saved[k];
  } catch { /* storage unavailable or corrupt: ignore */ }
}
function saveCityOverride(key, coords) {
  try {
    const saved = JSON.parse(localStorage.getItem(KEY) || '{}');
    saved[key] = coords;
    localStorage.setItem(KEY, JSON.stringify(saved));
  } catch { /* ignore */ }
}

// "Pune", or "18.52, 73.85" -> { coords, label } or null.
function parseResolveInput(text, resolveCity, table) {
  const s = String(text || '').trim();
  if (!s) return null;
  const m = s.match(/^(-?\d+(?:\.\d+)?)\s*[, ]\s*(-?\d+(?:\.\d+)?)$/);
  if (m) {
    const lat = Number(m[1]), lng = Number(m[2]);
    if (lat >= 6 && lat <= 38 && lng >= 67 && lng <= 98) return { coords: [lat, lng], label: lat + ', ' + lng };
    return null; // outside India
  }
  const r = resolveCity(s, table);
  return r.coords ? { coords: r.coords, label: r.matchedAs } : null;
}


